from fastapi import FastAPI
from pydantic import BaseModel, Field

app = FastAPI(title='AI Gateway')

class PromptRequest(BaseModel):
    query: str = Field(min_length=1, max_length=4000)
    risk: str = Field(default='low', pattern='^(low|medium|high)$')
    max_tokens: int = Field(default=500, ge=1, le=4000)

def route(body: PromptRequest) -> dict:
    if body.risk == 'high':
        return {'model': 'quality-model', 'approval_required': True}
    if body.max_tokens < 800:
        return {'model': 'fast-model', 'approval_required': False}
    return {'model': 'quality-model', 'approval_required': False}

@app.post('/route')
def choose_model(body: PromptRequest):
    return {'request': body.model_dump(), 'route': route(body)}

