from dataclasses import dataclass

@dataclass
class Chunk:
    text: str
    source: str
    version: str

def score(query: str, chunk: Chunk) -> int:
    terms = set(query.lower().split())
    return sum(term in chunk.text.lower() for term in terms)

def retrieve(query: str, chunks: list[Chunk], version: str):
    candidates = [c for c in chunks if c.version == version]
    return sorted(candidates, key=lambda c: score(query, c), reverse=True)[:3]

chunks = [
    Chunk('Retry HTTP 429 with exponential backoff.', 'limits.md', '2.1'),
    Chunk('Version 1 used a fixed retry delay.', 'legacy.md', '1.0'),
]
for chunk in retrieve('how should HTTP 429 retry', chunks, '2.1'):
    print(chunk.source, chunk.text)

DESTRUCTIVE = {'delete_user', 'restart_service', 'deploy_production'}

def authorize(tool: str, approved: bool, role: str) -> dict:
    if tool in DESTRUCTIVE and not approved:
        return {'allowed': False, 'reason': 'human approval required'}
    if tool == 'deploy_production' and role != 'release-manager':
        return {'allowed': False, 'reason': 'role is not permitted'}
    return {'allowed': True}

for args in [
    ('read_logs', False, 'engineer'),
    ('restart_service', False, 'engineer'),
    ('deploy_production', True, 'engineer'),
    ('deploy_production', True, 'release-manager'),
]:
    print(args, authorize(*args))
